-- verdicts: 5 baris
INSERT OR IGNORE INTO verdicts (id, escrow, worker, eligible, alasan, tx_hash, created_at) VALUES (1, '0x7b7ce50d82e9f72603ad6c32ded475056212162b', '0x920bef978cffda8a030d4aa3c9d3aa5ecaa3c1a0', 1, 'Bukti memenuhi semua kriteria wajib: menjelaskan cara menjalankan backend, mencantumkan endpoint REST dengan method dan deskripsi, menjelaskan struktur file/folder, menyebutkan konfigurasi environment, dan ditulis dalam format Markdown yang bisa diakses publik.', '0xc791bf207d54acf351f28cade191e3265fcda14936a6c0ec05aefb2b1e6e15d2', 1786280924427);
INSERT OR IGNORE INTO verdicts (id, escrow, worker, eligible, alasan, tx_hash, created_at) VALUES (2, '0x447b5c62fc5b52488644a98a31743b079320394f', '0x920bef978cffda8a030d4aa3c9d3aa5ecaa3c1a0', 0, 'Bukti yang diberikan adalah kode smart contract Solidity, bukan dokumentasi backend yang diminta. Tidak menjelaskan cara menjalankan backend, tidak ada daftar endpoint REST, tidak menjelaskan struktur file/folder, dan tidak menyebutkan konfigurasi environment.', '0xcda015adb2df96af498012012118ad27b940a69b289e16cc64676da1eb7c6b41', 1786281227091);
INSERT OR IGNORE INTO verdicts (id, escrow, worker, eligible, alasan, tx_hash, created_at) VALUES (3, '0xe6c22ca1475922cfb6b94a37d47b88f0ec0cc26b', '0x920bef978cffda8a030d4aa3c9d3aa5ecaa3c1a0', 1, 'Bukti memenuhi semua kriteria wajib: menjelaskan cara menjalankan backend, mencantumkan endpoint REST dengan method dan deskripsi, menjelaskan struktur file/folder, menyebutkan konfigurasi environment, dan ditulis dalam format Markdown yang dapat diakses publik.', '0x7157093c2d226fb2015008036518f904e3b976715fddd12b6c83019350d72ec8', 1786284117749);
INSERT OR IGNORE INTO verdicts (id, escrow, worker, eligible, alasan, tx_hash, created_at) VALUES (4, '0x9b5b5668b67cc9cbfce0f44ee723bf59531bc2ea', '0x920bef978cffda8a030d4aa3c9d3aa5ecaa3c1a0', 0, 'Bukti yang diberikan adalah kode smart contract Solidity, bukan dokumentasi backend yang diminta dalam aturan bounty. Bukti tidak memenuhi salah satu kriteria wajib yang ditetapkan.', '0x9fac25d1f3c375ef8de462f202b20d6b60290db1d7f975725b1e99d68bb07653', 1786284128242);
INSERT OR IGNORE INTO verdicts (id, escrow, worker, eligible, alasan, tx_hash, created_at) VALUES (5, '0x39f1abad8fdceda3a571865d68e010d1a83512f2', '0x920bef978cffda8a030d4aa3c9d3aa5ecaa3c1a0', 1, 'Bukti memenuhi seluruh kriteria wajib: mencantumkan perintah instalasi dan menjalankan backend, daftar endpoint REST beserta method dan deskripsi, struktur file/folder dengan fungsinya, serta konfigurasi environment termasuk RPC_URL. Bukti berformat Markdown dan disertai URL raw publik.', '0xff21644fd61b7838250093bb69cfb613deb73c22488ca644d30a0abc69f94ff7', 1786290972184);

